* Control Block
.control
* 1. Operating Point (Power)
op
let p_total = -i(VDD) * 1.8
print p_total

* 2. AC Analysis (Open-loop gain, PSRR+, Bandwidth)
ac dec 100 1 100MEG

let aol_db = vdb(AOL)
let aol_ph = 180/PI * cph(v(AOL))
let vdd_gain_db = vdb(Vout)
let psrr_pos_db = aol_db - vdd_gain_db

meas ac aol_dc find aol_db at=10
meas ac vdd_gain_dc find vdd_gain_db at=10
meas ac psrr_dc find psrr_pos_db at=10

* 3-dB frequency
let aol_3db_target = aol_dc - 3.0
meas ac f_3db when aol_db=aol_3db_target fall=1

* Unity-gain frequency and phase margin
meas ac fun when aol_db=0 fall=1
meas ac ph_fun find aol_ph when aol_db=0 fall=1
let pm = 180 + ph_fun
print pm

quit
.endc
.end

